```js
const clients = new Map(); // client_id -> Map(key -> value)

function isNonEmptyString(v) {
  return typeof v === 'string' && v.length > 0;
}

function requireNonEmptyString(args, name) {
  if (!isNonEmptyString(args[name])) {
    throw new Error(`${name} must be a non-empty string`);
  }
}

function requireKnownClient(client_id) {
  if (!clients.has(client_id)) {
    throw new Error(`unknown client: ${client_id}`);
  }
}

export async function listTools() {
  return [
    {
      name: 'open_client',
      description: 'Open a new client with an independent key/value map.',
      inputSchema: {
        type: 'object',
        properties: {
          client_id: { type: 'string', description: 'Unique non-empty client identifier.' }
        },
        required: ['client_id']
      }
    },
    {
      name: 'client_put',
      description: 'Store a value for a key owned by a client.',
      inputSchema: {
        type: 'object',
        properties: {
          client_id: { type: 'string' },
          key: { type: 'string' },
          value: { type: 'string' }
        },
        required: ['client_id', 'key', 'value']
      }
    },
    {
      name: 'client_get',
      description: 'Retrieve a value for a key owned by a client.',
      inputSchema: {
        type: 'object',
        properties: {
          client_id: { type: 'string' },
          key: { type: 'string' }
        },
        required: ['client_id', 'key']
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  switch (name) {
    case 'open_client': {
      requireNonEmptyString(args, 'client_id');
      const client_id = args.client_id;
      if (!clients.has(client_id)) {
        clients.set(client_id, new Map());
      }
      return { content: [{ type: 'text', text: `client ${client_id} opened` }] };
    }
    case 'client_put': {
      requireNonEmptyString(args, 'client_id');
      requireNonEmptyString(args, 'key');
      requireNonEmptyString(args, 'value');
      requireKnownClient(args.client_id);
      clients.get(args.client_id).set(args.key, args.value);
      return { content: [{ type: 'text', text: 'ok' }] };
    }
    case 'client_get': {
      requireNonEmptyString(args, 'client_id');
      requireNonEmptyString(args, 'key');
      requireKnownClient(args.client_id);
      const map = clients.get(args.client_id);
      if (!map.has(args.key)) {
        throw new Error(`unknown key: ${args.key}`);
      }
      return { content: [{ type: 'text', text: map.get(args.key) }] };
    }
    default:
      throw new Error(`unknown tool: ${name}`);
  }
}
```

